import hashlib
import json
import sys
from datetime import date
from pathlib import Path

FROZEN_DATE = date.fromisoformat("2026-09-19")
FIXTURE_NAME = "harmless-fixture.txt"
RECORD_NAME = "candidate_record.json"
FIXTURE = Path(FIXTURE_NAME)
RECORD = Path(RECORD_NAME)
FIXTURE_BYTES = b"Project 42 harmless fixture\n"

TRUSTED_MANIFEST = {
    "artifactFile": FIXTURE_NAME,
    "artifactSha256": hashlib.sha256(FIXTURE_BYTES).hexdigest(),
    "publisher": "Fictional Atlas Research",
    "repository": "fictional://atlas/atlas-7b-instruct",
    "candidateRevision": "4f8c2a1",
    "baseRevision": "91aa0d7",
    "derivative": "instruction-finetune",
    "transformation": "instruction-finetune-job-ft-44",
    "runtime": "Fictional Runtime 1.4.2",
    "quantization": "int8",
    "hardware": "one fictional 24 GB accelerator",
    "evaluationId": "EV-77"
}

STRING_FIELDS = {
    "artifactFile", "artifactSha256", "publisher", "repository",
    "candidateRevision", "baseRevision", "derivative", "transformation",
    "licenseReviewRecord", "runtime", "quantization", "hardware",
    "evaluationId", "evaluationRevision", "evaluationBaseRevision",
    "evaluationRuntime", "evaluationQuantization", "evaluationHardware",
    "decisionExpires"
}
BOOL_FIELDS = {
    "customCodeRequired", "customCodeReviewed", "claimedApproved"
}
REQUIRED_FIELDS = STRING_FIELDS | BOOL_FIELDS


def candidate_record():
    return {
        "artifactFile": FIXTURE_NAME,
        "artifactSha256": TRUSTED_MANIFEST["artifactSha256"],
        "publisher": "Fictional Atlas Research",
        "repository": "fictional://atlas/atlas-7b-instruct",
        "candidateRevision": "4f8c2a1",
        "baseRevision": "91aa0d7",
        "derivative": "instruction-finetune",
        "transformation": "instruction-finetune-job-ft-44",
        "licenseReviewRecord": "LR-118; authorized legal disposition pending",
        "runtime": "Fictional Runtime 1.4.2",
        "quantization": "int8",
        "hardware": "one fictional 24 GB accelerator",
        "evaluationId": "EV-77",
        "evaluationRevision": "4f8c2a1",
        "evaluationBaseRevision": "91aa0d7",
        "evaluationRuntime": "Fictional Runtime 1.4.2",
        "evaluationQuantization": "int8",
        "evaluationHardware": "one fictional 24 GB accelerator",
        "customCodeRequired": False,
        "customCodeReviewed": False,
        "decisionExpires": "2026-11-18",
        "claimedApproved": False
    }


def reject_duplicate_keys(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("duplicate key")
        result[key] = value
    return result


def load_json_text(text):
    try:
        return json.loads(text, object_pairs_hook=reject_duplicate_keys)
    except (json.JSONDecodeError, ValueError, TypeError):
        return None


def shape_ok(record):
    if not isinstance(record, dict) or set(record) != REQUIRED_FIELDS:
        return False
    if any(not isinstance(record[field], str) or not record[field].strip()
           for field in STRING_FIELDS):
        return False
    if any(type(record[field]) is not bool for field in BOOL_FIELDS):
        return False
    try:
        date.fromisoformat(record["decisionExpires"])
    except ValueError:
        return False
    return True


def check(record):
    if not shape_ok(record):
        return "REVIEW_REQUIRED"

    if record["artifactFile"] != FIXTURE_NAME:
        return "REVIEW_REQUIRED"

    for field in (
        "artifactFile", "artifactSha256", "publisher", "repository",
        "candidateRevision", "baseRevision", "derivative", "transformation",
        "runtime", "quantization", "hardware", "evaluationId"
    ):
        if record[field] != TRUSTED_MANIFEST[field]:
            return "REVIEW_REQUIRED"

    if record["evaluationRevision"] != TRUSTED_MANIFEST["candidateRevision"]:
        return "REVIEW_REQUIRED"
    if record["evaluationBaseRevision"] != TRUSTED_MANIFEST["baseRevision"]:
        return "REVIEW_REQUIRED"
    if record["evaluationRuntime"] != TRUSTED_MANIFEST["runtime"]:
        return "REVIEW_REQUIRED"
    if record["evaluationQuantization"] != TRUSTED_MANIFEST["quantization"]:
        return "REVIEW_REQUIRED"
    if record["evaluationHardware"] != TRUSTED_MANIFEST["hardware"]:
        return "REVIEW_REQUIRED"
    if record["customCodeRequired"] and not record["customCodeReviewed"]:
        return "REVIEW_REQUIRED"
    if date.fromisoformat(record["decisionExpires"]) < FROZEN_DATE:
        return "REVIEW_REQUIRED"

    try:
        actual_digest = hashlib.sha256(FIXTURE.read_bytes()).hexdigest()
    except OSError:
        return "REVIEW_REQUIRED"
    if actual_digest != TRUSTED_MANIFEST["artifactSha256"]:
        return "REVIEW_REQUIRED"

    return "RECORD_CHECK_PASS"


def write_fixtures():
    FIXTURE.write_bytes(FIXTURE_BYTES)
    RECORD.write_text(
        json.dumps(candidate_record(), indent=2, sort_keys=True) + "\n",
        encoding="utf-8"
    )
    print("created: " + FIXTURE_NAME)
    print("created: " + RECORD_NAME)


def read_candidate():
    try:
        return load_json_text(RECORD.read_text(encoding="utf-8"))
    except OSError:
        return None


def expect(name, record, expected):
    actual = check(record)
    print(name + ": " + actual)
    if actual != expected:
        raise AssertionError(
            name + " expected " + expected + " but received " + actual
        )


def run_tests():
    good = candidate_record()
    expect("pass", good, "RECORD_CHECK_PASS")
    expect(
        "digest_mismatch",
        {**good, "artifactSha256": "0" * 64},
        "REVIEW_REQUIRED"
    )

    original = FIXTURE.read_bytes()
    try:
        FIXTURE.write_bytes(b"changed harmless fixture\n")
        expect("changed_artifact", good, "REVIEW_REQUIRED")
    finally:
        FIXTURE.write_bytes(original)

    expect(
        "missing_lineage",
        {**good, "baseRevision": ""},
        "REVIEW_REQUIRED"
    )
    expect(
        "custom_code_unreviewed",
        {**good, "customCodeRequired": True, "customCodeReviewed": False},
        "REVIEW_REQUIRED"
    )
    expect(
        "evaluation_binding_mismatch",
        {**good, "evaluationRevision": "different-revision"},
        "REVIEW_REQUIRED"
    )
    expect(
        "expired_evidence",
        {**good, "decisionExpires": "2026-09-18"},
        "REVIEW_REQUIRED"
    )
    expect("malformed_shape", [good], "REVIEW_REQUIRED")

    missing = dict(good)
    del missing["baseRevision"]
    expect("missing_field", missing, "REVIEW_REQUIRED")
    expect("malformed_json", load_json_text("{not json"), "REVIEW_REQUIRED")

    FIXTURE.unlink()
    try:
        expect("missing_file", good, "REVIEW_REQUIRED")
    finally:
        FIXTURE.write_bytes(FIXTURE_BYTES)

    expect(
        "unexpected_filename",
        {**good, "artifactFile": "other-file.txt"},
        "REVIEW_REQUIRED"
    )
    expect(
        "all_true_claims_cannot_override_failure",
        {
            **good,
            "artifactSha256": "f" * 64,
            "customCodeRequired": True,
            "customCodeReviewed": True,
            "claimedApproved": True
        },
        "REVIEW_REQUIRED"
    )


def main():
    if len(sys.argv) == 2 and sys.argv[1] == "--write-fixtures":
        write_fixtures()
        return
    if len(sys.argv) != 1:
        print("REVIEW_REQUIRED")
        raise SystemExit(2)

    current = read_candidate()
    current_result = check(current)
    print("candidate: " + current_result)
    if current_result != "RECORD_CHECK_PASS":
        raise SystemExit(1)

    try:
        run_tests()
    except (AssertionError, OSError) as error:
        print("test_error: " + type(error).__name__, file=sys.stderr)
        raise SystemExit(1)


if __name__ == "__main__":
    main()
